<?php require_once '../config.php';if(admin())header('Location: dashboard.php');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{$q=db()->prepare('SELECT * FROM admins WHERE username=?');$q->execute([$_POST['username']]);$a=$q->fetch();if($a&&password_verify($_POST['password'],$a['password_hash'])){$_SESSION['admin_id']=$a['id'];header('Location: dashboard.php');exit;} $err='Kullanıcı adı veya şifre hatalı.';}catch(Throwable $x){$err='Önce install.php ile kurulumu tamamla.';}}?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>YSC Admin</title><link rel="stylesheet" href="../assets/style.css"></head><body><section class="section"><h2>YSC Admin Panel</h2><?php if($err):?><p class="gold"><?=e($err)?></p><?php endif;?><form class="admin" method="post"><input name="username" placeholder="Kullanıcı adı"><input type="password" name="password" placeholder="Şifre"><button class="btn">Giriş Yap</button></form></section></body></html>
